    seeds=[(i,j,int(g[i,j])) for i in range(H) for j in range(W) if g[i,j]!=bg and g[i,j]!=rc]
    out=g.copy().tolist()
    for p,q,v in seeds:
        for d in ((0,-1),(0,1),(-1,0),(1,0)):
            a,b=p,q
            while True:
                a+=d[0]; b+=d[1]
                if not(0<=a<H and 0<=b<W): break
                if g[a,b]==rc:
                    out[int(a)][int(b)]=v; break
    return out

